PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO meta VALUES ('schema_version','1');
CREATE TABLE IF NOT EXISTS folios(id INTEGER PRIMARY KEY, numero TEXT UNIQUE NOT NULL, fecha_recepcion TEXT, responsable TEXT NOT NULL DEFAULT '', activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)));
CREATE TABLE IF NOT EXISTS personas(curp TEXT PRIMARY KEY, nombre TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS trabajos(id INTEGER PRIMARY KEY, folio_id INTEGER NOT NULL REFERENCES folios(id), curp TEXT NOT NULL REFERENCES personas(curp), legajo INTEGER NOT NULL CHECK(legajo>0), digitalizador TEXT NOT NULL DEFAULT '', estado TEXT NOT NULL DEFAULT 'Recibido', estado_desde TEXT NOT NULL, recibido TEXT, fisicos INTEGER CHECK(fisicos>=0), fuera_broche INTEGER NOT NULL DEFAULT 0 CHECK(fuera_broche>=0), carpetas INTEGER NOT NULL DEFAULT 0 CHECK(carpetas IN(0,1)), notas TEXT NOT NULL DEFAULT '', activo INTEGER NOT NULL DEFAULT 1 CHECK(activo IN(0,1)), UNIQUE(folio_id,curp,legajo));
CREATE TABLE IF NOT EXISTS conteos(id INTEGER PRIMARY KEY, trabajo_id INTEGER NOT NULL REFERENCES trabajos(id), cantidad INTEGER NOT NULL CHECK(cantidad>0), nota TEXT NOT NULL DEFAULT '', activo INTEGER NOT NULL DEFAULT 1, creado TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalogos(id INTEGER PRIMARY KEY, tipo TEXT NOT NULL CHECK(tipo IN('documento','incidencia')), codigo TEXT NOT NULL, carpeta TEXT NOT NULL DEFAULT '', titulo TEXT NOT NULL, descripcion TEXT NOT NULL DEFAULT '', accion TEXT NOT NULL DEFAULT '', activo INTEGER NOT NULL DEFAULT 1, UNIQUE(tipo,codigo));
CREATE TABLE IF NOT EXISTS incidencias(id INTEGER PRIMARY KEY, trabajo_id INTEGER NOT NULL REFERENCES trabajos(id), catalogo_id INTEGER REFERENCES catalogos(id), codigo_snapshot TEXT NOT NULL DEFAULT '', documento TEXT NOT NULL DEFAULT '', problema TEXT NOT NULL, accion TEXT NOT NULL DEFAULT '', estado TEXT NOT NULL DEFAULT 'Abierta' CHECK(estado IN('Abierta','Resuelta','Anulada')), creado TEXT NOT NULL, resuelto TEXT);
CREATE TABLE IF NOT EXISTS historial(id INTEGER PRIMARY KEY, trabajo_id INTEGER NOT NULL REFERENCES trabajos(id), estado TEXT NOT NULL, inicio TEXT NOT NULL, fin TEXT, motivo TEXT NOT NULL, operador TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auditoria(id INTEGER PRIMARY KEY, fecha TEXT NOT NULL, operador TEXT NOT NULL, entidad TEXT NOT NULL, registro TEXT NOT NULL, accion TEXT NOT NULL, antes TEXT, despues TEXT, motivo TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS fuentes(id INTEGER PRIMARY KEY, hash TEXT UNIQUE NOT NULL, nombre TEXT NOT NULL, fecha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS origen(id INTEGER PRIMARY KEY, fuente_id INTEGER NOT NULL REFERENCES fuentes(id), hoja TEXT NOT NULL, fila INTEGER NOT NULL, contenido TEXT NOT NULL, UNIQUE(fuente_id,hoja,fila));
CREATE TABLE IF NOT EXISTS pendientes(id INTEGER PRIMARY KEY, origen_id INTEGER REFERENCES origen(id), tipo TEXT NOT NULL, detalle TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'Pendiente');
CREATE TABLE IF NOT EXISTS ejecuciones(id INTEGER PRIMARY KEY, huella TEXT UNIQUE NOT NULL, origen_id INTEGER REFERENCES origen(id), curp TEXT NOT NULL, fecha TEXT NOT NULL, payload TEXT NOT NULL, trabajo_id INTEGER REFERENCES trabajos(id), ambito TEXT NOT NULL DEFAULT 'Sin asignar' CHECK(ambito IN('Sin asignar','Legajo','CURP completa')), valido INTEGER NOT NULL DEFAULT 1, observacion TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS tareas(id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'Pendiente' CHECK(estado IN('Pendiente','En curso','En espera','Bloqueada','Hecha')), trabajo_id INTEGER REFERENCES trabajos(id), notas TEXT NOT NULL DEFAULT '', activo INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_trabajos_curp ON trabajos(curp);
CREATE INDEX IF NOT EXISTS idx_historial_trabajo ON historial(trabajo_id);
CREATE INDEX IF NOT EXISTS idx_ejecuciones_trabajo ON ejecuciones(trabajo_id,fecha);
